CREATE TABLE closet_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, category text NOT NULL, color text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'ACTIVE', confidence text NOT NULL DEFAULT 'CONFIRMED', photo_url text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,category,code), CHECK(status IN ('ACTIVE','EVALUATION','ALTERATION','LOANED','DONATED','SOLD','DISCARDED')), CHECK(confidence IN ('CONFIRMED','OBSERVED','INFERRED','UNKNOWN','OUTDATED')));
ALTER TABLE closet_items ENABLE ROW LEVEL SECURITY; ALTER TABLE closet_items FORCE ROW LEVEL SECURITY;
CREATE POLICY closet_items_self ON closet_items FOR ALL TO closet_app USING (user_id = nullif(current_setting('app.user_id',true),'')::uuid AND tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (user_id = nullif(current_setting('app.user_id',true),'')::uuid AND tenant_id = nullif(current_setting('app.tenant_id',true),'')::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON closet_items TO closet_app;
